/* ============================================
   ACTION BAR
   A summary line and the primary actions, docked
   to the bottom of a long list or form
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

/* Base */
.ds-action-bar {
  /* The surface the bar reads as one with: the blur's tint with the blur
     on, the fill with it off. An override hook: a bar over a container
     points it at that container's fill. */
  --ds-action-bar-surface: var(--color-bg-page-primary);
  /* How far above the bar the blur reaches, so the content dissolves into
     it rather than stopping at its edge. */
  --ds-action-bar-blur-reach: var(--gap-1500);
  position: relative;
  /* Its own stacking context, so the blur's z-index of -1 paints behind
     the summary and the actions but never behind the content it covers. */
  isolation: isolate;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--gap-300) var(--gap-500);
  box-sizing: border-box;
  inline-size: 100%;
  padding-block: var(--padding-400);
  padding-inline: var(--padding-500);
}

/* Sticky: holds to the bottom edge of its scroll container. */
.ds-action-bar--sticky {
  position: sticky;
  inset-block-end: 0;
  z-index: var(--layer-sticky);
}

/* Blur: the stack reaches above the bar, behind its content. The space
   above the bar in flow is the same reach, so at the end of the scroll
   the last row clears the blur instead of resting under it. */
.ds-action-bar--blur {
  margin-block-start: var(--ds-action-bar-blur-reach);
}

.ds-action-bar__blur.ds-progressive-blur {
  --ds-progressive-blur-tint: var(--ds-action-bar-surface);
  inset-block-start: calc(var(--ds-action-bar-blur-reach) * -1);
  z-index: -1;
}

/* Solid: the bar's own surface, parted from the content by a hairline. */
.ds-action-bar--solid {
  background-color: var(--ds-action-bar-surface);
  border-block-start: var(--border-025) solid var(--color-divider);
}

/* Summary: takes the room at the start; a long line wraps rather than
   pushing the actions off the bar. */
.ds-action-bar__summary {
  flex: 1 1 auto;
  min-inline-size: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-primary);
  overflow-wrap: anywhere;
}

/* Actions: hold the end edge, on the summary's row or wrapped below it. */
.ds-action-bar__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--gap-300);
  margin-inline-start: auto;
}

} /* @layer rift.components */

import React from 'react';
import { ProgressiveBlur } from '../ProgressiveBlur/ProgressiveBlur';
import './ActionBar.css';

/** Props owned by ActionBar itself; everything else falls through to the root `<div>`. */
type ActionBarOwnProps = {
  /**
   * The summary line at the bar's start, such as "23 students still to
   * mark". It is a polite live region, so a count that changes while the
   * reader works is announced once it settles.
   */
  summary?: React.ReactNode;
  /**
   * The actions at the bar's end, typically one or two Buttons with the
   * primary action last. On a narrow bar they wrap below the summary and
   * hold the end edge.
   */
  actions?: React.ReactNode;
  /**
   * Whether the bar holds to the bottom of its scroll container while the
   * content scrolls under it. Off, it sits in flow after the content.
   */
  sticky?: boolean;
  /**
   * Whether the content fades under a progressive blur that reaches above
   * the bar. Off, the bar is a solid surface with a hairline at its top
   * edge.
   */
  blur?: boolean;
  /** Additional CSS classes on the root. */
  className?: string;
};

export interface ActionBarProps
  extends ActionBarOwnProps,
    Omit<React.ComponentPropsWithRef<'div'>, keyof ActionBarOwnProps> {}

/**
 * A bar docked to the bottom of a long list or form, holding a summary
 * line and the primary actions, with the content fading under a
 * progressive blur rather than being cut off at the bar's edge. The
 * forwarded ref and any unrecognised props target the root `<div>`, so a
 * host that wants a landmark passes `role="region"` with an `aria-label`.
 */
export function ActionBar({
  summary,
  actions,
  sticky = true,
  blur = true,
  className = '',
  ref,
  ...rest
}: ActionBarProps) {
  const baseClass = 'ds-action-bar';
  const classes = [
    baseClass,
    sticky && `${baseClass}--sticky`,
    blur ? `${baseClass}--blur` : `${baseClass}--solid`,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div {...rest} ref={ref} className={classes}>
      {blur && <ProgressiveBlur side="bottom" tinted className={`${baseClass}__blur`} />}
      {/* Always rendered, even empty, so a summary that arrives later is
          announced: a live region inserted with its text already in it is
          not. */}
      <div className={`${baseClass}__summary`} aria-live="polite" aria-atomic="true">
        {summary}
      </div>
      {actions != null && actions !== false && <div className={`${baseClass}__actions`}>{actions}</div>}
    </div>
  );
}
